          return cdp.send(method as "Page.getLayoutMetrics", params);
        captures += 1;
        captureStarted.resolve();
        return new Promise(() => {});
      },
    } as unknown as CDPSession;
    const snapshotOf = () =>
      ServerBrowserPage.snapshot({
        page,
