            canGoBack: false,
            canGoForward: false,
            updatedAt: "2026-10-02T00:00:00.000Z",
          },
        }));
        const closed: PreviewEvent[] = opened.map((event, index) => ({
          type: "closed",
          threadId: event.threadId,
          tabId: event.tabId,
          serverEpoch: event.serverEpoch,
          revision: opened.length + index + 1,
          createdAt: event.createdAt,
