            if (!AsyncResult.isSuccess(result)) return;
            observed.push(result.value);
            if (result.value === closed[closed.length - 1]) {
              Deferred.doneUnsafe(sawLast, Exit.void);
            }
          },
          { immediate: true },
        );
        yield* Effect.addFinalizer(() =>
          Effect.sync(() => {
            unsubscribe();
            registry.dispose();
          }),
        );

