              ratio: page.ratio * (zoom / page.zoom),
              width: page.width * (page.zoom / zoom),
              height: page.height * (page.zoom / zoom),
            };
            // Desktop zoom applies after this renderer read, before the next layout reply.
            zoom = page.zoom;
