      const clock = vi.spyOn(performance, "now").mockReturnValue(0);
      yield* Effect.addFinalizer(() => Effect.sync(() => clock.mockRestore()));
      yield* Effect.addFinalizer(() => Effect.sync(() => committed.resolve()));
