            operation: "evaluate",
            input: { expression: "42" },
          }),
        ).toBe("evaluated");
        expect(contexts[0]!.page.close).not.toHaveBeenCalled();
        expect((yield* manager.list({ threadId: scope.thread.threadId })).sessions).toHaveLength(1);
      }),
