    const page = {
      frames: () => [mainFrame],
      mainFrame: () => mainFrame,
      viewportSize: () => ({ width: 800, height: 600 }),
      evaluate: never,
      ariaSnapshot: never,
      on: () => {},
    } as unknown as Page;
    // The compositor still draws, so only the snapshot deadline can answer.
    const cdp = {
      send: (method: string) =>
        method === "Page.captureScreenshot" ? Promise.resolve({ data: "" }) : never(),
    } as unknown as CDPSession;
    const settled = ServerBrowserPage.snapshot({
      page,
      cdp,
      renderScale: 1,
      consoleEntries: [],
      networkEntries: [],
      actionTimeline: [],
    }).then(() => null, ServerBrowserPage.toOperationError);
    await vi.advanceTimersByTimeAsync(15_000);
    expect(await settled).toMatchObject({ tag: "PreviewAutomationTimeoutError" });
  });
});

