        page.evaluate.mockImplementationOnce(async () => {
          started.resolve();
          return release.promise;
        });
        const click = vi.fn(async () => {});
        page.locator.mockReturnValue({
          scrollIntoViewIfNeeded: async () => {},
          boundingBox: async () => ({ x: 0, y: 0, width: 10, height: 10 }),
          click,
        } as never);
