        let now = performance.now();
        const clock = vi.spyOn(performance, "now").mockImplementation(() => now);
        yield* Effect.addFinalizer(() => Effect.sync(() => clock.mockRestore()));
        const snapshot = yield* broker
          .invoke<PreviewAutomationSnapshot>({
