// Chromium sizes a capture by the clip, its scale, and the display ratio net of page zoom.
it.live.each([
  {
    name: "desktop at display ratio 1.5",
    desktop: true,
    page: { ratio: 1.5, width: 1280, height: 800, zoom: 1 },
    scrollY: 0,
    size: { width: 1280, height: 800 },
    clipY: 0,
  },
  {
    name: "desktop resized to a phone",
    desktop: true,
    page: { ratio: 1, width: 390, height: 844, zoom: 1 },
    scrollY: 0,
    size: { width: 390, height: 844 },
    clipY: undefined,
  },
  {
    name: "desktop zoom changes during a scrolled snapshot",
    desktop: true,
    page: { ratio: 3, width: 640, height: 400, zoom: 2 },
    scrollY: 100,
    size: { width: 1280, height: 800 },
    clipY: 200,
  },
  {
    name: "headless",
    desktop: false,
    page: { ratio: 2, width: 1280, height: 800, zoom: 1 },
    scrollY: 0,
    size: { width: 640, height: 400 },
    clipY: 0,
  },
])("snapshot captures the page's own viewport: $name", ({ desktop, page, scrollY, size, clipY }) =>
  Effect.scoped(
    Effect.gen(function* () {
      desktopRendersNext = desktop;
      const { browser, broker, tabId } = yield* ready;
      yield* browser.attachViewer(viewerInput(tabId, false));
      const context = desktop ? desktopConnections[0]!.context : contexts[0]!;
      const display = desktop ? page.ratio / page.zoom : 1;
      let zoom = 1;
      const clips: Array<{ y: number } | undefined> = [];
      let metricsReads = 0;
      for (const session of context.sessions) {
        const send = session.send.getMockImplementation()!;
        session.send.mockImplementation(async (method, input) => {
          if (
            method === "Runtime.evaluate" &&
            String((input as { expression?: string })?.expression).includes("devicePixelRatio")
          ) {
            metricsReads += 1;
            const value = {
              ratio: page.ratio * (zoom / page.zoom),
              width: page.width * (page.zoom / zoom),
              height: page.height * (page.zoom / zoom),
            };
            // Desktop zoom applies after this renderer read, before the next layout reply.
            zoom = page.zoom;
            return { result: { value } };
          }
          if (method === "Page.getLayoutMetrics") {
            return { cssVisualViewport: { pageX: 0, pageY: scrollY, zoom } };
          }
          if (method === "Page.captureScreenshot") {
            const clip = (
              input as { clip?: { y: number; width: number; height: number; scale: number } }
            )?.clip;
            clips.push(clip);
            const header = Buffer.alloc(24);
            header.write("IHDR", 12);
            header.writeUInt32BE(
              Math.round((clip ? clip.width * clip.scale : page.width * page.zoom) * display),
              16,
            );
            header.writeUInt32BE(
              Math.round((clip ? clip.height * clip.scale : page.height * page.zoom) * display),
              20,
            );
            return { data: header.toString("base64") };
          }
          return send(method, input);
        });
      }
      const result = yield* broker.invoke<PreviewAutomationSnapshot>({
        scope,
        tabId,
        operation: "snapshot",
        input: {},
      });
      const png = Buffer.from(result.screenshot.data, "base64");
      expect(result.screenshot).toMatchObject(size);
      expect({ width: png.readUInt32BE(16), height: png.readUInt32BE(20) }).toEqual(size);
      expect(clips.map((clip) => clip?.y)).toEqual([clipY]);
      if (!desktop) expect(metricsReads).toBe(0);
    }),
  ).pipe(Effect.provide(layer)),
);

it.live.each(["wait", "pause", "capture", "resume"] as const)(
  "a stalled snapshot %s releases the tab queue and capture lock without leaking a paused viewer",
  (stage) =>
    Effect.scoped(
      Effect.gen(function* () {
        const { browser, broker, tabId } = yield* ready;
        const viewer = yield* browser.attachViewer(viewerInput(tabId, stage === "wait"));
        if (stage === "wait") {
          yield* viewer.input({ type: "takeControl" });
          yield* viewer.input({ type: "key", action: "down", key: "Shift", code: "ShiftLeft" });
          yield* viewer.input({ type: "mouse", action: "down", button: "left", x: 10, y: 20 });
        }
        // Recovery must reach a viewer even when its output queue is full.
        stallViewer(viewer, { _tag: "viewport", width: 1280, height: 800 });
        const { page, sessions } = contexts[0]!;
        const session = sessions.at(-1)!;
        const blocked = Promise.withResolvers<void>();
        const release = Promise.withResolvers<void>();
        const send = session.send.getMockImplementation()!;
        let streaming = true;
        let stalled = false;
        session.send.mockImplementation(async (method, input) => {
          if (
            !stalled &&
            ((stage === "wait" && method === "Page.captureScreenshot") ||
              (stage === "pause" && method === "Page.stopScreencast") ||
              (stage === "resume" && method === "Page.startScreencast"))
          ) {
            stalled = true;
            blocked.resolve();
            if (stage !== "wait") await release.promise;
          }
          if (stalled && stage === "wait") await release.promise;
          const result = await send(method, input);
          if (method === "Page.stopScreencast") streaming = false;
          if (method === "Page.startScreencast") streaming = true;
          return result;
        });
        const cdp = sessions[0]!;
        if (stage === "wait") {
          session.detach.mockImplementation(() => release.promise);
          const tabSend = cdp.send.getMockImplementation()!;
          cdp.send.mockImplementation(async (method, input) => {
            const result = await tabSend(method, input);
            if (method.startsWith("Input.dispatch")) await release.promise;
            return result;
          });
        }
        if (stage === "capture") {
          page.ariaSnapshot.mockImplementationOnce(async () => {
            blocked.resolve();
            await release.promise;
            return '- button "delete" [ref=e1]';
          });
        }
        vi.useFakeTimers({ toFake: ["setTimeout", "clearTimeout", "Date"] });
        yield* Effect.addFinalizer(() =>
          Effect.sync(() => {
            release.resolve();
            vi.useRealTimers();
          }),
        );
        if (stage === "wait") {
          session.emit("Page.screencastFrame", { data: "ZnJhbWU=", sessionId: 1 });
